from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib,json,re
base='https://halifax.bidsandtenders.ca/Module/Tenders/en'
root=Path('products/services/halifax-offline-rfq')
raw=(root/'raw/halifax-tender-portal.html').read_bytes()
assert hashlib.sha256(raw).hexdigest()=='df80e1d3a1652dd63af2b8970c1bc269d0a7c973aa837ca2ef5cbefe500d5bd4'
class Portal(HTMLParser):
    def __init__(self):
        super().__init__(); self.row=None; self.cell=None; self.rows=[]; self.links=[]
    def handle_starttag(self,tag,attrs):
        if tag=='tr': self.row=[]
        if tag in ('th','td') and self.row is not None: self.cell=[]
        if tag=='a' and (href:=dict(attrs).get('href')):
            url=urljoin(base,href); parsed=urlsplit(url)
            if parsed.scheme=='https' and parsed.netloc==urlsplit(base).netloc and re.search(r'/Detail[s]?/',parsed.path,re.I): self.links.append(url)
    def handle_data(self,data):
        if self.cell is not None: self.cell.append(data)
    def handle_endtag(self,tag):
        if tag in ('td','th') and self.cell is not None and self.row is not None:
            self.row.append(' '.join(' '.join(self.cell).split())); self.cell=None
        if tag=='tr' and self.row is not None:
            if any(self.row): self.rows.append(self.row)
            self.row=None; self.cell=None
parser=Portal(); parser.feed(raw.decode('utf-8-sig',errors='replace'))
terms=re.compile(r'inventory|reconcil|spreadsheet|data quality|data clean|asset register|catalogu|digitiz',re.I)
result={'source_url':base,'source_sha256':hashlib.sha256(raw).hexdigest(),'rendered_table_row_count':len(parser.rows),'rendered_table_rows':parser.rows[:60],'keyword_rows':[row for row in parser.rows if terms.search(' '.join(row))][:30],'candidate_detail_urls':sorted(set(parser.links))[:60],'scope':'Static HTML extraction. Links, row text and keyword matches are leads. JavaScript-loaded opportunities may be absent. Confirm the original request, closing date and lot terms before drawing a buyer conclusion.'}
output=root/'director-portal-screen.json'; output.write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n'); assert json.loads(output.read_text())==result
print(json.dumps({k:v for k,v in result.items() if k!='rendered_table_rows'},ensure_ascii=False)[:5000])
